import 'package:flutter/material.dart';import 'package:uuid/uuid.dart';import '../models/employee.dart';import '../services/storage_service.dart';class EmployeeDetailsScreen extends StatefulWidget{final Employee employee;const EmployeeDetailsScreen({super.key,required this.employee});@override State<EmployeeDetailsScreen> createState()=>_S();}class _S extends State<EmployeeDetailsScreen>{late Employee e;@override void initState(){super.initState();e=widget.employee;}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(e.name)),body:ListView(padding:const EdgeInsets.all(16),children:[Text('الوظيفة: ${e.role}'),Text('المرتب: ${e.salaryMonthly.toStringAsFixed(0)} ج'),Text('الحضور: ${e.attendance.length} | الغياب التقريبي: ${e.absenceDays}'),Text('السلف: ${e.totalAdvances.toStringAsFixed(0)} ج'),Text('المتبقي: ${e.remainingSalary.toStringAsFixed(0)} ج'),const SizedBox(height:16),Row(children:[Expanded(child:ElevatedButton.icon(onPressed:_advance,icon:const Icon(Icons.money_off),label:const Text('سلفة'))),const SizedBox(width:8),Expanded(child:ElevatedButton.icon(onPressed:_attendance,icon:const Icon(Icons.check),label:const Text('حضور اليوم'))]),const Divider(),...e.advances.map((a)=>ListTile(title:Text('${a.amount.toStringAsFixed(0)} ج'),subtitle:Text(a.date.toString().substring(0,10))))]));Future<void>_advance()async{final x=TextEditingController();showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('سلفة'),content:TextField(controller:x,keyboardType:TextInputType.number),actions:[TextButton(onPressed:()async{e.advances.add(Advance(id:const Uuid().v4(),amount:double.tryParse(x.text)??0,date:DateTime.now()));await StorageService.saveEmployee(e);if(mounted){Navigator.pop(context);setState((){});}},child:const Text('حفظ'))]));}Future<void>_attendance()async{final d=DateTime.now().toIso8601String().substring(0,10);if(!e.attendance.contains(d))e.attendance.add(d);await StorageService.saveEmployee(e);setState((){});}}
